def search(lst, x): 
 left, right = 0, len(lst) - 1 
 while left <= right: 
     mid = (left + right) // 2 
     if lst[mid] == x: 
         return mid 
     elif lst[mid] < x: 
         left = mid + 1 
     else: 
         right = mid - 1 
 else: 
     return -1

