def permutations(word):    if len(word) == 1: 
        return [word] 
    result = [] 
    for i in range(len(word)): 
        first_letter = word[i] 
        remaining_letters = word[:i] + word[i+1:] 
        for permutation in permutations(remaining_letters): 
            result.append(first_letter + permutation) 
    return result

