def max_sum_subsequence(arr): 
    dp = [0] * len(arr) 
    dp[0] = arr[0] 
    for i in range(1, len(arr)): 
        if arr[i] >= arr[i-1]: 
            dp[i] = dp[i-1] + arr[i] 
        else: 
            dp[i] = arr[i] 
    max_sum = max(dp) 
    return max_sum

